class Solution {
  public int[][] generateSchedule(int n) {
    if (n < 5) return new int[0][];
    for (int seed = 0; ; seed++) {
      int[][] res = attempt(n, new java.util.Random(seed));
      if (res != null) return res;
    }
  }

  private int[][] attempt(int n, java.util.Random rnd) {
    int total = n * (n - 1);
    boolean[][] used = new boolean[n][n];
    int[] rem = new int[n];
    java.util.Arrays.fill(rem, 2 * (n - 1));
    int[][] res = new int[total][2];
    int lastA = -1, lastB = -1;
    for (int step = 0; step < total; step++) {
      int bestA = -1, bestB = -1, bestScore = -1;
      for (int a = 0; a < n; a++) {
        if (a == lastA || a == lastB) continue;
        for (int b = 0; b < n; b++) {
          if (b == a || b == lastA || b == lastB || used[a][b]) continue;
          int score = rem[a] * 1000 + rem[b] * 1000 + (step == 0 ? 0 : rnd.nextInt(3));
          if (score > bestScore) {
            bestScore = score;
            bestA = a;
            bestB = b;
          }
        }
      }
      if (bestA < 0) return null;
      used[bestA][bestB] = true;
      rem[bestA]--;
      rem[bestB]--;
      res[step][0] = bestA;
      res[step][1] = bestB;
      lastA = bestA;
      lastB = bestB;
    }
    return res;
  }
}
